277: // ApplyEvents reparses a raw event stream into a record. Used to recompute
278: // token aggregates after parser fixes without re-running model calls.
279: func ApplyEvents(record *RunRecord, raw []byte) {
280: 	text, tokens, cost, sessionID, toolCalls, eventCount := parseEvents(raw)
281: 	record.Text = text
282: 	record.Tokens = tokens
283: 	record.Cost = cost
284: 	record.SessionID = sessionID
285: 	record.ToolCalls = toolCalls
286: 	record.EventCount = eventCount
287: 	record.Success = text != "" && record.ExitCode == 0
288: }
