351: 			return nil
352: 		}
353: 		data, err := os.ReadFile(path)
354: 		if err != nil || len(data) > 1<<20 {
355: 			return nil
356: 		}
357: 		if strings.Contains(string(data), "\u2014") {
358: 			found = true
